# Surah Ta-Ha (chapter 20) — part 9: ayat 81-90 (IDs 2429-2438)
SURAH = 20

ENTRIES = {
2429: (
"جو جو پاکیزہ چیزیں ہم نے تمہیں دی ہیں ان میں سے کھاؤ — اور اس میں سرکشی نہ کرو ورنہ تم پر میرا غضب نازل ہو جائے گا — اور جس پر میرا غضب نازل ہو وہ گر گیا",
"""۱۔ اللہ کا حکم — پاکیزہ رزق کھاؤ؛ سرکشی نہ کرو؛ غضبِ الٰہی سے بچو۔
۲۔ ’’كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَلَا تَطْغَوْا فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي وَمَن يَحْلِلْ عَلَيْهِ غَضَبِي فَقَدْ هَوَىٰ‘‘ — جو جو پاکیزہ چیزیں ہم نے تمہیں دی ہیں ان میں سے کھاؤ — اور اس میں سرکشی نہ کرو ورنہ تم پر میرا غضب نازل ہو جائے گا — اور جس پر میرا غضب نازل ہو وہ گر گیا — یعنی کھاؤ وہ پاکیزہ چیزیں جو ہم نے تمہیں دی ہیں اور اس میں سرکشی نہ کرو ورنہ تم پر میرا غضب نازل ہو گا اور جس پر میرا غضب نازل ہو وہ گر گیا۔
۳۔ عملی سبق: اللہ کی نعمتوں میں حد سے نہ بڑھو؛ اس کا خوف رکھو۔"""
),
2430: (
"اور بے شک میں توبہ کرنے والے — ایمان لانے والے — نیک عمل کرنے والے — پھر ہدایت اختیار کرنے والے کے لیے بہت زیادہ بخشش دینے والا ہوں",
"""۱۔ اللہ کی مغفرت — توبہ؛ ایمان؛ نیک عمل؛ ہدایت؛ سب بخشے جاتے ہیں۔
۲۔ ’’وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَىٰ‘‘ — اور بے شک میں توبہ کرنے والے — ایمان لانے والے — نیک عمل کرنے والے — پھر ہدایت اختیار کرنے والے کے لیے بہت زیادہ بخشش دینے والا ہوں — یعنی اور بے شک میں بہت بخشش دینے والا ہوں اس کے لیے جو توبہ کرے ایمان لائے نیک عمل کرے پھر ہدایت اختیار کرے۔
۳۔ عملی سبق: توبہ کرو؛ ایمان لاؤ؛ نیک عمل کرو؛ اللہ کی بخشش پاؤ۔"""
),
2431: (
"اور آپ اپنی قوم سے پہلے جلدی کیوں کر آئے اے موسیٰ؟",
"""۱۔ اللہ کا سوال — موسیٰؑ نے قوم سے پہلے آ جانے کی وجہ؛ رب کے سامنے جوابدہی۔
۲۔ ’’وَمَا أَعْجَلَكَ عَن قَوْمِكَ يَا مُوسَىٰ‘‘ — اور آپ اپنی قوم سے پہلے جلدی کیوں کر آئے اے موسیٰ؟ — یعنی کیا وجہ ہے کہ آپ نے اپنی قوم سے پہلے جلدی کر لی اے موسیٰ؟
۳۔ عملی سبق: اللہ کے سامنے ہر عمل کی ذمہ داری ہے؛ سوچ سمجھ کر چلو۔"""
),
2432: (
"موسیٰؑ نے کہا وہ میرے پیچھے ہیں — اور میں آپ کے پاس جلدی آیا تاکہ آپ راضی ہوں اے میرے رب",
"""۱۔ موسیٰؑ کا جواب — قوم پیچھے آ رہی ہے؛ آپ کو خوش کرنے کے لیے جلدی؛ ایمان۔
۲۔ ’’قَالَ هُمْ أُولَاءِ عَلَىٰ أَثَرِي وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ‘‘ — موسیٰؑ نے کہا وہ میرے پیچھے ہیں — اور میں آپ کے پاس جلدی آیا تاکہ آپ راضی ہوں اے میرے رب — یعنی موسیٰؑ نے کہا وہ میرے پیچھے ہیں اور میں آپ کے پاس جلدی آیا اے میرے رب تاکہ آپ راضی ہوں۔
۳۔ عملی سبق: اللہ کو خوش کرنے کے لیے جلدی کرو؛ اس کے احکام میں تیزی سے چلو۔"""
),
2433: (
"اللہ نے فرمایا بے شک ہم نے آپ کے بعد آپ کی قوم کو آزمایا ہے — اور انہیں سامری نے گمراہ کیا",
"""۱۔ اللہ کا اعلان — بنی اسرائیل گمراہ ہو گئے؛ سامری نے گمراہ کیا؛ اللہ کی آزمائش۔
۲۔ ’’قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِن بَعْدِكَ وَأَضَلَّهُمُ السَّامِرِيُّ‘‘ — اللہ نے فرمایا بے شک ہم نے آپ کے بعد آپ کی قوم کو آزمایا ہے — اور انہیں سامری نے گمراہ کیا — یعنی اللہ نے فرمایا ہم نے آپ کے بعد آپ کی قوم کو آزمایا اور سامری نے انہیں گمراہ کیا۔
۳۔ عملی سبق: گمراہ لوگوں کی پیروی نہ کرو؛ اللہ کی ہدایت پر رہو۔"""
),
2434: (
"پس موسیٰؑ اپنی قوم کے پاس غضبناک اور غمزدہ ہو کر واپس آئے — کہا اے میری قوم کیا تمہارے رب نے تم سے اچھا وعدہ نہیں کیا تھا؟ کیا تمہارے اوپر عہد بہت لمبا ہو گیا؟ یا تم نے اپنے رب کے غضب کو اپنے اوپر چاہا — اور میرے وعدے کی خلاف ورزی کی؟",
"""۱۔ موسیٰؑ کا غضب — قوم نے گمراہ ہونے کا سبب وعدہ خلافی؛ گولڈن بچھڑے کی عبادت۔
۲۔ ’’فَرَجَعَ مُوسَىٰ إِلَىٰ قَوْمِهِ غَضْبَانَ أَسِفًا قَالَ يَا قَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا أَفَطَالَ عَلَيْكُمُ الْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِي‘‘ — پس موسیٰؑ اپنی قوم کے پاس غضبناک اور غمزدہ ہو کر واپس آئے — کہا اے میری قوم کیا تمہارے رب نے تم سے اچھا وعدہ نہیں کیا تھا؟ کیا تمہارے اوپر عہد بہت لمبا ہو گیا؟ یا تم نے اپنے رب کے غضب کو اپنے اوپر چاہا — اور میرے وعدے کی خلاف ورزی کی؟ — یعنی پس موسیٰؑ اپنی قوم کی طرف غضبناک اور غمزدہ ہو کر واپس آئے کہا اے میری قوم کیا تمہارے رب نے تم سے اچھا وعدہ نہیں کیا تھا کیا تم پر عہد لمبا ہو گیا یا تم نے اپنے رب کا غضب اپنے اوپر لادنا چاہا اور میرے وعدے کی خلاف ورزی کی۔
۳۔ عملی سبق: اللہ کے وعدے یاد رکھو؛ اس کے عہد پر ثابت رہو؛ گمراہ ہونے سے بچو۔"""
),
2435: (
"انہوں نے کہا ہم نے اپنے اختیار سے آپ کے وعدے کی خلاف ورزی نہیں کی — لیکن ہم سے دشمن کی زیور کی بوجھ اٹھوایا گیا تھا — پس ہم نے اسے پھینک دیا — اور اسی طرح سامری نے پھینکا",
"""۱۔ بنی اسرائیل کا عذر — دشمنوں کے زیور سے مجبور؛ اللہ کے فعل؛ قصہ۔
۲۔ ’’قَالُوا مَا أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَا أَوْزَارًا مِّن زِينَۃِ الْقَوْمِ فَقَذَفْنَاهَا فَكَذَٰلِكَ أَلْقَى السَّامِرِيُّ‘‘ — انہوں نے کہا ہم نے اپنے اختیار سے آپ کے وعدے کی خلاف ورزی نہیں کی — لیکن ہم سے دشمن کی زیور کی بوجھ اٹھوایا گیا تھا — پس ہم نے اسے پھینک دیا — اور اسی طرح سامری نے پھینکا — یعنی انہوں نے کہا ہم نے اپنے اختیار سے آپ کے وعدے کی خلاف ورزی نہیں کی لیکن ہمارے اوپر دشمن کی زینت کا بوجھ ڈالا گیا تھا پس ہم نے اسے پھینک دیا اور اسی طرح سامری نے بھی پھینکا۔
۳۔ عملی سبق: ذمہ داری سے بچنے کے بہانے نہ بناؤ؛ دلی سچائی سے کام لو۔"""
),
2436: (
"پس اس نے ان کے لیے ایک بچھڑا نکالا — جسم جس سے آواز نکلتی تھی — انہوں نے کہا یہ تمہارا معبود ہے اور موسیٰ کا معبود ہے — پس وہ بھول گیا",
"""۱۔ سامری کا گولڈن بچھڑا — آواز والا جسم؛ لوگوں نے عبادت کی؛ موسیٰؑ کی غیر موجودگی میں گمراہی۔
۲۔ ’’فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُ خُوَارٌ فَقَالُوا هَٰذَا إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ‘‘ — پس اس نے ان کے لیے ایک بچھڑا نکالا — جسم جس سے آواز نکلتی تھی — انہوں نے کہا یہ تمہارا معبود ہے اور موسیٰ کا معبود ہے — پس وہ بھول گیا — یعنی پس اس نے ان کے لیے بچھڑا نکالا جس کا جسم تھا اور آواز نکلتی تھی اور انہوں نے کہا یہ تمہارا معبود ہے اور موسیٰ کا معبود ہے پس وہ بھول گیا۔
۳۔ عملی سبق: اللہ کے سوا کسی چیز کو معبود نہ بناؤ؛ صرف اسی کی عبادت کرو۔"""
),
2437: (
"کیا وہ نہیں دیکھتے کہ وہ ان کی باتوں کا جواب نہیں دیتا — اور نہ انہیں کوئی نقصان پہنچا سکتا ہے اور نہ نفع دے سکتا ہے",
"""۱۔ سامری کے بچھڑے کی بے قید — نہ جواب؛ نہ نقصان؛ نہ نفع؛ عقل استعمال کرو۔
۲۔ ’’أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا‘‘ — کیا وہ نہیں دیکھتے کہ وہ ان کی باتوں کا جواب نہیں دیتا — اور نہ انہیں کوئی نقصان پہنچا سکتا ہے اور نہ نفع دے سکتا ہے — یعنی کیا وہ نہیں دیکھتے کہ یہ ان کی باتوں کا جواب نہیں دیتا اور نہ انہیں کوئی نقصان پہنچا سکتا ہے اور نہ انہیں نفع دے سکتا ہے۔
۳۔ عملی سبق: عقل استعمال کرو؛ بتوں اور جھوٹے معبودوں کو پہچانو؛ صرف اللہ کی عبادت کرو۔"""
),
2438: (
"اور یقیناً ہارون نے ان سے پہلے کہا تھا اے میری قوم تم تو اس کے ذریعے آزمائے گئے — اور بے شک تمہارا رب رحمن ہے — پس میری اطاعت کرو اور میری بات مانو",
"""۱۔ ہارونؑ کی تنبیہ — بچھڑے سے آزمائش؛ رحمن اللہ؛ اطاعت؛ موسیٰؑ کی غیر موجودگی میں ہمت۔
۲۔ ’’وَلَقَدْ قَالَ لَهُمْ هَارُونُ مِن قَبْلُ يَا قَوْمِ إِنَّمَا فُتِنتُم بِهِ وَإِنَّ رَبَّكُمُ الرَّحْمَٰنُ فَاتَّبِعُونِي وَأَطِيعُوا أَمْرِي‘‘ — اور یقیناً ہارون نے ان سے پہلے کہا تھا اے میری قوم تم تو اس کے ذریعے آزمائے گئے — اور بے شک تمہارا رب رحمن ہے — پس میری اطاعت کرو اور میری بات مانو — یعنی اور ہارونؑ نے ان سے کہا تھا اے میری قوم تم تو اس کے ذریعے آزمائے گئے بے شک تمہارا رب رحمن ہے پس میری پیروی کرو اور میرے حکم پر چلو۔
۳۔ عملی سبق: ہدایت کا علم رکھنے والوں کی اطاعت کرو؛ اللہ کی راہ پر رہو۔"""
),
}
